netfilter: nf_conntrack_sip: fix Content-Length u32
 truncation in sip_help_tcp()
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

sip_help_tcp() parses the SIP Content-Length header with
simple_strtoul(), which returns unsigned long, but stores the result in
unsigned int clen.  On 64-bit systems, values exceeding UINT_MAX are
silently truncated before computing the SIP message boundary.

For example, Content-Length 4294967328 (2^32 + 32) is truncated to 32,
causing the parser to miscalculate where the current message ends.  The
loop then treats trailing data in the TCP segment as a second SIP
message and processes it through the SDP parser.

Fix this by changing clen to unsigned long to match the return type of
simple_strtoul(), and reject Content-Length values that exceed the
remaining TCP payload length.

Fixes: f5b321bd37fb ("netfilter: nf_conntrack_sip: add TCP support")
Signed-off-by: Lukas Johannes Möller <research@johannes-moeller.dev>
Signed-off-by: Florian Westphal <fw@strlen.de>

Here is the root cause:
The bug is caused by storing the return value of simple_strtoul() (unsigned long) into an unsigned int variable 'clen'. On 64-bit systems, Content-Length values exceeding UINT_MAX are silently truncated before computing the SIP message boundary, leading to miscalculation of where the current message ends and potentially incorrect processing of trailing data as a new SIP message.

Here is the patch:

 static int sip_help_tcp(struct sk_buff *skb, unsigned int protoff,
 			struct nf_conn *ct, enum ip_conntrack_info ctinfo)
 {
 	struct tcphdr *th, _tcph;
 	unsigned int dataoff, datalen;
-	unsigned int matchoff, matchlen, clen;
+	unsigned int matchoff, matchlen;
 	unsigned int msglen, origlen;
 	const char *dptr, *end;
 	s16 diff, tdiff = 0;
 	int ret = NF_ACCEPT;
+	unsigned long clen;
 	bool term;

 	if (ctinfo != IP_CT_ESTABLISHED &&
 	    ctinfo != IP_CT_ESTABLISHED_REPLY)
 		return NF_ACCEPT;

 	/* No Data ? */
 	th = skb_header_pointer(skb, protoff, sizeof(_tcph), &_tcph);
 	if (th == NULL)
 		return NF_ACCEPT;
 	dataoff = protoff + th->doff * 4;
 	if (dataoff >= skb->len)
 		return NF_ACCEPT;

 	nf_ct_refresh(ct, sip_timeout * HZ);

 	if (unlikely(skb_linearize(skb)))
 		return NF_DROP;

 	dptr = skb->data + dataoff;
 	datalen = skb->len - dataoff;
 	if (datalen < strlen("SIP/2.0 200"))
 		return NF_ACCEPT;

 	while (1) {
 		if (ct_sip_get_header(ct, dptr, 0, datalen,
 				      SIP_HDR_CONTENT_LENGTH,
 				      &matchoff, &matchlen) <= 0)
 			break;

 		clen = simple_strtoul(dptr + matchoff, (char **)&end, 10);
 		if (dptr + matchoff == end)
 			break;

+		if (clen > datalen)
+			break;
+
 		term = false;
 		for (; end + strlen("\r\n\r\n") <= dptr + datalen; end++) {
 			if (end[0] == '\r' && end[1] == '\n' &&
 			    end[2] == '\r' && end[3] == '\n') {
 				term = true;
 				break;
 			}
 		}
 		if (!term)
 			break;
 		end += strlen("\r\n\r\n") + clen;

 		msglen = origlen = end - dptr;
 		if (msglen > datalen)
 			return NF_ACCEPT;

 		ret = process_sip_msg(skb, ct, protoff, dataoff,
 				      &dptr, &msglen);
 		/* process_sip_* functions report why this packet is dropped */
 		if (ret != NF_ACCEPT)
 			break;
 		diff     = msglen - origlen;
 		tdiff   += diff;

 		dataoff += msglen;
 		dptr    += msglen;
 		datalen  = datalen + diff - msglen;
 	}

 	if (ret == NF_ACCEPT && ct->status & IPS_NAT_MASK) {
 		const struct nf_nat_sip_hooks *hooks;

 		hooks = rcu_dereference(nf_nat_sip_hooks);
 		if (hooks)
 			hooks->seq_adjust(skb, protoff, tdiff);
 	}

 	return ret;
 }



